// Ticker lookup
async function lookupTicker(){
  const t = document.getElementById('ticker-input').value.trim().toUpperCase();
  if(!t) return;
  const res = document.getElementById('ticker-result');
  res.innerHTML = '<span class="loading">Loading '+t+'…</span>';
  try{
    const d = await get('data/ticker-360.json');
    const tk = d.tickers||{};
    const data = tk[t];
    if(!data){
      res.innerHTML = '<span class="err">Ticker '+t+' not in 360° universe ('+Object.keys(tk).length+' tickers indexed)</span>';
      return;
    }
    const doms = data.domains||{};
    const dnames = Object.keys(doms);
    res.innerHTML = '<p style="margin-bottom:8px"><span class="ticker" style="font-size:1.2rem">'+t+'</span> <span class="badge t360">'+data.coverage_count+' domains</span></p>' +
      '<div class="t360bar" style="margin-bottom:12px">'+dnames.map(n=>'<span>'+n+'</span>').join('')+'</div>' +
      dnames.map(n=>{
        const dd = doms[n];
        const td = dd.data||{};
        return '<details class="audit" style="margin-bottom:6px"><summary>'+n+' <span style="color:var(--mut)">as of '+ago(dd.as_of)+'</span></summary><pre>'+JSON.stringify(td,null,1).slice(0,1000)+'</pre></details>';
      }).join('');
  }catch(e){
    res.innerHTML = '<span class="err">'+e.message+'</span>';
  }
}
document.getElementById('ticker-input')?.addEventListener('keypress', e=>{ if(e.key==='Enter') lookupTicker(); });

document.getElementById('calibNote').textContent = DATA.calibration_quality?.available === false
  ? 'Calibration unavailable; rankings withheld'
  : alerts.calibration_active ? 'Calibration configured; see input availability below' : 'Uncalibrated legacy weights';
